1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/url"
10		"sort"
11		"strings"
12	)
13	
14	// Route is one configured route: an id, accepted methods, a path prefix and
15	// the upstream URL requests on that route are forwarded to. An optional
16	// queryTransforms list rewrites the request query string after the route has
17	// been selected.
18	type Route struct {
19		ID              string            `json:"id"`
20		Methods         []string          `json:"methods"`
21		PathPrefix      string            `json:"pathPrefix"`
22		Upstream        string            `json:"upstream"`
23		QueryTransforms []*QueryTransform `json:"-"`
24	}
25	
26	// QueryTransform is one rule in a route's queryTransforms array: op is
27	// "set", "remove" or "rename"; name is matched against decoded parameter
28	// names, value (set only) is used literally, and to (rename only) is the
29	// literal replacement name.
30	type QueryTransform struct {
31		Op    string `json:"op"`
32		Name  string `json:"name"`
33		Value string `json:"value"`
34		To    string `json:"to"`
35	}
36	
37	// routeJSON mirrors Route, keeping queryTransforms as raw JSON so null,
38	// wrong types and malformed rules can be reported with the route's location
39	// instead of as a generic decode error.
40	type routeJSON struct {
41		ID              string          `json:"id"`
42		Methods         []string        `json:"methods"`
43		PathPrefix      string          `json:"pathPrefix"`
44		Upstream        string          `json:"upstream"`
45		QueryTransforms json.RawMessage `json:"queryTransforms"`
46	}
47	
48	// UnmarshalJSON decodes a route object and eagerly validates its
49	// queryTransforms (if present); the location matches ParseConfig's
50	// "route N" numbering so the reason can identify the route and rule.
51	func (route *Route) UnmarshalJSON(data []byte) error {
52		var rj routeJSON
53		if err := json.Unmarshal(data, &rj); err != nil {
54			return err
55		}
56		idx := routeUnmarshalIndex
57		routeUnmarshalIndex++
58		route.ID = rj.ID
59		route.Methods = rj.Methods
60		route.PathPrefix = rj.PathPrefix
61		route.Upstream = rj.Upstream
62	
63		if len(rj.QueryTransforms) == 0 {
64			return nil // field absent
65		}
66		loc := fmt.Sprintf("route %d", idx+1)
67		transforms, f := parseQueryTransforms(rj.QueryTransforms, loc, rj.ID)
68		if f != nil {
69			return f
70		}
71		route.QueryTransforms = transforms
72		return nil
73	}
74	
75	// parseQueryTransforms decodes and validates the raw queryTransforms array
76	// of one route. loc identifies the route; rule errors additionally carry a
77	// 1-based rule index.
78	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
79		body := strings.TrimSpace(string(raw))
80		if body == "null" {
81			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
82		}
83		var elems []json.RawMessage
84		if err := json.Unmarshal([]byte(body), &elems); err != nil {
85			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
86		}
87		transforms := make([]*QueryTransform, 0, len(elems))
88		for i, elem := range elems {
89			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
90			if string(bytes.TrimSpace(elem)) == "null" {
91				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
92			}
93			var fields map[string]json.RawMessage
94			if err := json.Unmarshal(elem, &fields); err != nil {
95				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
96			}
97	
98			qt := &QueryTransform{}
99			opRaw, ok := fields["op"]
100			switch {
101			case !ok:
102				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
103			case !jsonString(opRaw, &qt.Op):
104				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
105			case qt.Op != "set" && qt.Op != "remove" && qt.Op != "rename":
106				return nil, failuref("invalid_config", "%s: unknown op %q (only set, remove and rename are supported)", ruleLoc, qt.Op)
107			}
108	
109			nameRaw, ok := fields["name"]
110			switch {
111			case !ok:
112				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
113			case !jsonString(nameRaw, &qt.Name):
114				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
115			case qt.Name == "":
116				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
117			}
118	
119			valueRaw, hasValue := fields["value"]
120			toRaw, hasTo := fields["to"]
121			switch qt.Op {
122			case "set":
123				if !hasValue {
124					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
125				}
126				if !jsonString(valueRaw, &qt.Value) {
127					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
128				}
129			case "remove":
130				if hasValue {
131					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
132				}
133			case "rename":
134				if hasValue {
135					return nil, failuref("invalid_config", "%s: rename must not include a value", ruleLoc)
136				}
137				switch {
138				case !hasTo:
139					return nil, failuref("invalid_config", "%s: rename requires a non-empty string to", ruleLoc)
140				case !jsonString(toRaw, &qt.To):
141					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
142				case qt.To == "":
143					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
144				}
145			}
146			transforms = append(transforms, qt)
147		}
148		return transforms, nil
149	}
150	
151	// jsonString decodes raw into s and reports whether raw is a JSON string
152	// (null, numbers, objects and arrays fail).
153	func jsonString(raw json.RawMessage, s *string) bool {
154		if len(raw) == 0 || raw[0] != '"' {
155			return false
156		}
157		return json.Unmarshal(raw, s) == nil
158	}
159	
160	// routeLabel renders the human-readable route location, adding the id when
161	// the configuration supplied one.
162	func routeLabel(loc, id string) string {
163		if id != "" {
164			return fmt.Sprintf("%s (id %q)", loc, id)
165		}
166		return loc
167	}
168	
169	// routeUnmarshalIndex is advanced while a config is decoded so nested route
170	// unmarshalling can report its 1-based position. Route objects only occur in
171	// the routes array; ParseConfig resets it before each decode.
172	var routeUnmarshalIndex int
173	
174	// Config is the resolve configuration: a flat array of routes.
175	type Config struct {
176		Routes []Route `json:"routes"`
177	}
178	
179	// Request is one resolution request: an HTTP method and a request target
180	// (path with an optional raw query string).
181	type Request struct {
182		Method string `json:"method"`
183		Target string `json:"target"`
184	}
185	
186	// Resolution is the successful result of matching a request.
187	type Resolution struct {
188		RouteID     string `json:"routeId"`
189		UpstreamURL string `json:"upstreamURL"`
190	}
191	
192	// Failure carries a stable machine-readable code and a human-readable reason.
193	type Failure struct {
194		Code       string   `json:"code"`
195		Reason     string   `json:"reason"`
196		Candidates []string `json:"candidates,omitempty"`
197	}
198	
199	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
200	
201	func failuref(code, format string, args ...any) *Failure {
202		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
203	}
204	
205	// ParseConfig parses and fully validates the route configuration.
206	func ParseConfig(data []byte) (*Config, *Failure) {
207		var cfg Config
208		routeUnmarshalIndex = 0
209		if err := json.Unmarshal(data, &cfg); err != nil {
210			if f, ok := err.(*Failure); ok {
211				return nil, f
212			}
213			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
214		}
215		if f := cfg.validate(); f != nil {
216			return nil, f
217		}
218		return &cfg, nil
219	}
220	
221	func (cfg *Config) validate() *Failure {
222		seenIDs := make(map[string]int, len(cfg.Routes))
223		for i := range cfg.Routes {
224			route := &cfg.Routes[i]
225			loc := fmt.Sprintf("route %d", i+1)
226			if route.ID == "" {
227				return failuref("invalid_config", "%s: id must be non-empty", loc)
228			}
229			if first, ok := seenIDs[route.ID]; ok {
230				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
231			}
232			seenIDs[route.ID] = i + 1
233	
234			if len(route.Methods) == 0 {
235				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
236			}
237			for _, method := range route.Methods {
238				switch {
239				case method == "":
240					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
241				case method == "*":
242					// Wildcard matching any legal method.
243				case !isToken(method):
244					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
245				}
246			}
247	
248			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
249				return f
250			}
251			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
252				return f
253			}
254		}
255		return nil
256	}
257	
258	func validatePrefix(prefix, loc, id string) *Failure {
259		switch {
260		case prefix == "" || prefix[0] != '/':
261			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
262		case prefix != "/" && strings.HasSuffix(prefix, "/"):
263			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
264		case strings.ContainsAny(prefix, "?#"):
265			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
266		case !validPercentEscapes(prefix):
267			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
268		}
269		return nil
270	}
271	
272	func validateUpstream(raw, loc, id string) *Failure {
273		if strings.ContainsAny(raw, "?#") {
274			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
275		}
276		u, err := url.Parse(raw)
277		if err != nil {
278			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
279		}
280		if u.Scheme != "http" && u.Scheme != "https" {
281			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
282		}
283		if u.Host == "" {
284			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
285		}
286		return nil
287	}
288	
289	// ParseRequest parses and validates one JSON request.
290	func ParseRequest(data []byte) (*Request, *Failure) {
291		var req Request
292		if err := json.Unmarshal(data, &req); err != nil {
293			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
294		}
295		switch {
296		case req.Method == "":
297			return nil, failuref("invalid_request", "method is required")
298		case !isToken(req.Method):
299			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
300		}
301		switch {
302		case req.Target == "" || req.Target[0] != '/':
303			return nil, failuref("invalid_request", "target must start with /")
304		case strings.Contains(req.Target, "#"):
305			return nil, failuref("invalid_request", "target must not contain a fragment")
306		case !validPercentEscapes(req.Target):
307			return nil, failuref("invalid_request", "target contains an invalid percent escape")
308		}
309		return &req, nil
310	}
311	
312	// Resolve matches a validated request against a validated configuration and
313	// computes the upstream URL. Failure codes are route_not_found and
314	// route_conflict.
315	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
316		path := req.Target
317		if i := strings.IndexByte(path, '?'); i >= 0 {
318			path = path[:i]
319		}
320	
321		type candidate struct {
322			route    *Route
323			concrete bool
324		}
325		var matched []candidate
326		for i := range cfg.Routes {
327			route := &cfg.Routes[i]
328			concrete, wildcard := methodMatch(route.Methods, req.Method)
329			if !concrete && !wildcard {
330				continue
331			}
332			if !prefixMatch(route.PathPrefix, path) {
333				continue
334			}
335			matched = append(matched, candidate{route, concrete})
336		}
337		if len(matched) == 0 {
338			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
339		}
340	
341		// Longest prefix wins.
342		bestLen := 0
343		for _, c := range matched {
344			if n := len(c.route.PathPrefix); n > bestLen {
345				bestLen = n
346			}
347		}
348		winners := matched[:0]
349		for _, c := range matched {
350			if len(c.route.PathPrefix) == bestLen {
351				winners = append(winners, c)
352			}
353		}
354	
355		// Among equal prefixes a concrete method beats the wildcard.
356		var concrete []candidate
357		for _, c := range winners {
358			if c.concrete {
359				concrete = append(concrete, c)
360			}
361		}
362		if len(concrete) > 0 {
363			winners = concrete
364		}
365		if len(winners) > 1 {
366			ids := make([]string, 0, len(winners))
367			for _, c := range winners {
368				ids = append(ids, c.route.ID)
369			}
370			sort.Strings(ids)
371			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
372			f.Candidates = ids
373			return nil, f
374		}
375	
376		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
377		if f != nil {
378			return nil, f
379		}
380		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
381	}
382	
383	// methodMatch reports whether the method list matches the request method
384	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
385	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
386		for _, m := range methods {
387			switch {
388			case m == "*":
389				wildcard = true
390			case m == method:
391				concrete = true
392			}
393		}
394		return concrete, wildcard
395	}
396	
397	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
398	// treated as a separator and the root prefix matches every origin-path.
399	func prefixMatch(prefix, path string) bool {
400		if prefix == "/" {
401			return true
402		}
403		if path == prefix {
404			return true
405		}
406		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
407	}
408	
409	// joinUpstream strips the route prefix from the request path and joins the
410	// remainder onto the upstream base path with exactly one slash at the
411	// junction. The base path is carried over byte for byte: joining never
412	// re-encodes, reorders or drops anything outside that junction. The raw
413	// query is preserved verbatim unless the route defines queryTransforms, in
414	// which case they rewrite it after route selection.
415	func joinUpstream(route *Route, path, target string) (string, *Failure) {
416		if _, err := url.Parse(route.Upstream); err != nil {
417			// Config validation already rejected this.
418			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
419		}
420	
421		var remainder string
422		switch {
423		case route.PathPrefix == "/":
424			// Root keeps the whole following path; "/" itself has an empty remainder.
425			if path != "/" {
426				remainder = path
427			}
428		default:
429			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
430		}
431	
432		// Slice the validated upstream raw so nothing outside the junction is
433		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
434		schemeEnd := strings.Index(route.Upstream, "://")
435		tail := route.Upstream[schemeEnd+3:]
436		hostPart, basePath := tail, ""
437		if i := strings.IndexByte(tail, '/'); i >= 0 {
438			hostPart, basePath = tail[:i], tail[i:]
439		}
440		joined := strings.TrimSuffix(basePath, "/")
441		if remainder == "" {
442			joined += "/" // the junction slash is kept even with no remaining path
443		} else {
444			joined += remainder
445		}
446	
447		result := route.Upstream[:schemeEnd+3] + hostPart + joined
448		query, f := applyQueryTransforms(route.QueryTransforms, target)
449		if f != nil {
450			return "", f
451		}
452		return result + query, nil
453	}
454	
455	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
456	func isToken(s string) bool {
457		if s == "" {
458			return false
459		}
460		for i := 0; i < len(s); i++ {
461			if !isTokenChar(s[i]) {
462				return false
463			}
464		}
465		return true
466	}
467	
468	func isTokenChar(c byte) bool {
469		switch {
470		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
471			return true
472		}
473		switch c {
474		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
475			return true
476		}
477		return false
478	}
479	
480	// validPercentEscapes checks that every "%' is followed by two hex digits.
481	// Matching and joining stay on raw strings, but malformed escapes are rejected
482	// up front for both prefixes and request targets.
483	func validPercentEscapes(s string) bool {
484		for i := 0; i < len(s); i++ {
485			if s[i] != '%' {
486				continue
487			}
488			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
489				return false
490			}
491			i += 2
492		}
493		return true
494	}
495	
496	func isHex(c byte) bool {
497		switch {
498		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
499			return true
500		}
501		return false
502	}
503

